#include <map>
#include <string>
#include <functional>

// Custom comparator using standard strict weak ordering
struct CaseInsensitiveCompare {
    bool operator()(const std::string& a, const std::string& b) const {
        // Assumes proper case conversion, ensuring SWO properties hold
        return std::lexicographical_compare(
            a.begin(), a.end(), 
            b.begin(), b.end(), 
            [](char ca, char cb) { return std::tolower(ca) < std::tolower(cb); }
        );
    }
}; 

int main() {
    // std::less<int> satisfies SWO
    std::map<int, int> m1;
    // CaseInsensitiveCompare must satisfy SWO for correct behavior
    std::map<std::string, int, CaseInsensitiveCompare> m2;
}
